using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 int OpeningKind(string role,int tier)=>Array.FindIndex(BuildDefinition.All,d=>d.Opening==role&&d.Tier==tier);
 async void RunOpeningChecks(){try{ClearEnemies();game.NoDiskSave=true;game.Building.Pieces.Clear();SyncStructures();Teleport(0,12);ClearEnemies();game.Craft.Researched.Clear();game.Craft.ResearchFocus.Clear();game.Craft.BenchTier=game.Craft.UnlockedTier=5;game.Craft.ResearchPoints=1000;game.Skills.Crafting.Level=5;game.Career.Level=5;game.Craft.Materials=Enumerable.Repeat(200,7).ToArray();
  foreach(string role in new[]{"doorway","window","gate"})MigrationChecks.Assert(BuildDefinition.All.Count(d=>d.Opening==role)==5,"One "+role+" in each tier");
  for(int tier=1;tier<=5;tier++){
   var wall=ExpeditionRecipe.All.First(r=>r.Kind=="build"&&r.Tier==tier&&BuildDefinition.All[r.Result].Function=="structure"&&BuildDefinition.All[r.Result].BaseKind==2);if(!game.Knows(wall))MigrationChecks.Assert(game.Research(Array.IndexOf(ExpeditionRecipe.All,wall)),"Wall research reachable / "+tier);
   foreach(string role in new[]{"doorway","window"}){int kind=OpeningKind(role,tier);var recipe=ExpeditionRecipe.All.First(r=>r.Kind=="build"&&r.Result==kind);MigrationChecks.Assert(game.Knows(recipe),"Wall research includes door/window without extra points");}
   int gate=OpeningKind("gate",tier);var gateRecipe=ExpeditionRecipe.All.First(r=>r.Kind=="build"&&r.Result==gate);if(!game.Knows(gateRecipe))MigrationChecks.Assert(game.Research(Array.IndexOf(ExpeditionRecipe.All,gateRecipe)),"Perimeter gate research chain / "+tier);
   foreach(string role in new[]{"doorway","window","gate"}){
    int kind=OpeningKind(role,tier);var d=BuildDefinition.All[kind];if(tier>1)MigrationChecks.Assert(d.Cost[tier+1]>0,"Exclusive zone material / "+d.Name);
    var piece=new BuildPiece{Kind=kind,Id="opening/test",X=0,Z=0,Y=0};var b=new ExpeditionBuilding((x,z)=>0);b.Pieces.Add(piece);
    if(role!="window"){MigrationChecks.Assert(!b.Free(0,0,0),"Closed leaf blocks passage");if(role=="gate")MigrationChecks.Assert(ExpeditionOpenings.SolidAt(piece,0,1.3,0,0),"Latch strip seals the closed gate center seam");piece.Open=true;MigrationChecks.Assert(b.Free(0,0,0),"Open leaf permits center passage");MigrationChecks.Assert(!b.Free(d.W/2-.1,0,0),"Open door retains solid side wall/posts");MigrationChecks.Assert(!b.Free(role=="gate"?-2.7:-.6,0,-.7),"Open leaf retains collision outside its closed footprint");}
    else MigrationChecks.Assert(!ExpeditionOpenings.SolidAt(piece,.4,1.55,0,0)&&ExpeditionOpenings.SolidAt(piece,1.35,1.55,0,0),"Window is a real aperture with solid sides");
    var deck=new BuildPiece{Kind=0,Yaw=90};var snapped=ExpeditionBuildSnap.Connect(deck,kind,1.4,0,0,1,0,0);MigrationChecks.Assert(Math.Abs(snapped.X)>1.5&&Math.Abs(snapped.Y-.5)<.001,"Rotated deck edge snap / "+role);if(role!="gate"){var roof=ExpeditionBuildSnap.Connect(snapped,7,snapped.X,snapped.Z,0,1,0,0,new[]{deck,snapped});MigrationChecks.Assert(Math.Abs(roof.X)<.001&&Math.Abs(roof.Z)<.001,"Roof centers over doorway/window room");}
   }
  }
  // Query real Godot colliders, not just the engine-independent footprint rules.
  player.Position=Ground(0,16);camera.Position=new(0,1.65f,0);var door=new BuildPiece{Kind=OpeningKind("doorway",5),Id="opening/physical",X=0,Z=12,Y=game.World.Height(0,12),Health=700};game.Building.Pieces.Add(door);SyncStructures();await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);
  bool Ray(float x,float y){var q=PhysicsRayQueryParameters3D.Create(new(x,(float)door.Y+y,14),new(x,(float)door.Y+y,10));q.Exclude=new(){player.GetRid()};return GetWorld3D().DirectSpaceState.IntersectRay(q).Count>0;}
  camera.LookAt(new Vector3(0,(float)door.Y+1.3f,12));MigrationChecks.Assert(AimedOpening()==door,"Aiming at the door exposes direct F interaction");MigrationChecks.Assert(Ray(0,1.3f),"Closed door blocks real hitscan");UseBlueprint(door.Id+"|door");MigrationChecks.Assert(door.Open,"Military door operates without generator");await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);MigrationChecks.Assert(!Ray(0,1.3f)&&Ray(1.2f,1.3f),"Open doorway allows hitscan but leaves side walls solid");
  var box=new Node3D();AddChild(box);PhysicsObstacle(box,new BoxShape3D{Size=new(.5f,1.5f,.5f)},new(0,(float)door.Y+.75f,12));await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);UseBlueprint(door.Id+"|door");MigrationChecks.Assert(door.Open&&game.Notice.Contains("blocked"),"Cannot close a door through an obstruction");box.QueueFree();
  game.Building.Pieces.Clear();var window=new BuildPiece{Kind=OpeningKind("window",5),Id="opening/window",X=0,Z=12,Y=door.Y,Health=700};game.Building.Pieces.Add(window);SyncStructures();await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);MigrationChecks.Assert(!Ray(.4f,1.55f)&&Ray(1.3f,1.55f)&&Ray(.4f,.5f),"Real window ray passes only through aperture");
  var copy=Json.Read<BuildPiece>(Json.Write(new BuildPiece{Kind=OpeningKind("gate",5),Open=true,DoorSwing=-1,Yaw=90}));MigrationChecks.Assert(copy.Open&&copy.DoorSwing==-1&&copy.Def.Opening=="gate","Gate opening/swing and stable blueprint survive save/snapshot");
  GD.Print("PASS / all 15 tiered openings: wall-linked research, gate progression/materials, rotated snap/roof support, real open/closed hitscan, solid jambs and open leaves, blocked closing, manual military hardware and saved swing");
  SetProcess(false);SetPhysicsProcess(false);ClearChildren(worldRoot);ClearChildren(terrainRoot);ClearChildren(buildRoot);props.Clear();chunks.Clear();await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);await ToSignal(GetTree(),SceneTree.SignalName.PhysicsFrame);GetTree().Quit();
 }catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
 async void CaptureOpenings(){try{CloseMenu();paused=true;ClearEnemies();terrainRoot.Visible=worldRoot.Visible=buildRoot.Visible=false;if(distantTerrain!=null)distantTerrain.Visible=false;weaponRoot.Visible=false;hudRoot.Visible=false;game.World.Changes.Time=900;
  for(int tier=1;tier<=5;tier++){var stage=new Node3D();AddChild(stage);Box(stage,new(0,-.1f,0),new(18,.2f,8),new(.20f,.24f,.20f));stage.AddChild(new DirectionalLight3D{RotationDegrees=new(-35,140,0),LightEnergy=1.2f});int i=0;foreach(string role in new[]{"doorway","window","gate"}){float x=i==0?-5.7f:i==1?-1.9f:3.5f;int kind=OpeningKind(role,tier);var node=Structure(new BuildPiece{Kind=kind},true);node.Position=new(x,0,0);stage.AddChild(node);stage.AddChild(new Label3D{Text=BuildDefinition.All[kind].Name,Position=new(x,3,0),FontSize=26,PixelSize=.009f,Billboard=BaseMaterial3D.BillboardModeEnum.Enabled});i++;}
   camera.Fov=52;camera.GlobalPosition=new(1,5,-13);camera.LookAt(new Vector3(0,1.2f,0));await ArtShot("openings-tier-"+tier);stage.QueueFree();await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);
  }GetTree().Quit();
 }catch(Exception e){GD.PushError(e.ToString());GetTree().Quit(1);}}
}
